head.script:
scwin.screenId = "jlddst20200";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_listApplntIsurCd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("listApplntIsurCd")))); } },
        { childId: "ipt_listApplntIsurNm", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("listApplntIsurNm")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#ipt_listApplntIsurNm").bind("change", function() {
            $c.util.getComponent('ipt_listApplntIsurCd').setValue("");
            $c.util.getComponent('ipt_listApplntIsurCd2').setValue("");
    });
    $("#ipt_listApplntIsurNm").bind("keypress", async function(e) {
            if (e.keyCode == 13) {
                if ($c.util.getComponent('ipt_listApplntIsurNm').getValue() !== $c.util.getComponent('ipt_listApplntIsurCd2').getValue()) {
                    $c.util.getComponent('ipt_listApplntIsurCd').setValue("");
                    $c.util.getComponent('ipt_listApplntIsurCd2').setValue("");
                }
                await scwin.fnSearchInit();
            }
    });
    $c.util.getComponent("dma_fnDownloadReq").set("method", "digitalCorpListPopSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "digital_corp_sub");
    await scwin.fnSearchInit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.init();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20200.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst20200.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_findDigitalListApplnt_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_findDigitalListApplnt_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_findDigitalListApplnt_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.findDigitalListApplnt();return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst20200.btn_findDigitalListApplnt_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_fnSearchInit_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnSearchInit_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnSearchInit(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20200.btn_fnSearchInit_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_fnDownload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnDownload_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnDownload_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnDownload();return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20200.btn_fnDownload_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/digital/digitalCorpListPop.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst20200.tx_fnDownload" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/digital/digitalCorpListPop.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst20200.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findDigitalListApplnt
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.findDigitalListApplnt = function () {
    /* sdd-asis-lifecycle:begin findDigitalListApplnt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.fnMarketType();
    const marketType = $c.util.getComponent('ipt_marketType').getValue();
    findDigitalListApplntIsurCd(marketType);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.fnMarketType();
    $c.util.getComponent('ipt_beginIndex').setValue("");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "digitalCorpListPopSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "digital_corp_sub");
    $("#searchForm").attr('onsubmit', 'return false;');
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    console.warn('[sdd] 미실현(재설계 분류 #128): fnLegendTooltip(' + "" + ')');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnMarketType
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnMarketType = function () {
    /* sdd-asis-lifecycle:begin fnMarketType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_marketType').setValue(0);
    let i = 0;
    let j = 0;
    const marketType1 = $("#ipt_marketType1").is(":checked");
    const marketType2 = $("#ipt_marketType2").is(":checked");
    if (marketType1 === true) {
        i = 1;
    }
    if (marketType2 === true) {
        j = 2;
    }
    const c = i + j;
    $c.util.getComponent('ipt_marketType').setValue(c);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch1 = async function () {
    /* sdd-asis-lifecycle:begin fnSearch1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "digitalCorpListPopSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "digital_corp_down");
    $("#searchForm").attr('onsubmit', '');
    await scwin.tx_fnDownload();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setDigitallistApplntInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_listApplntIsurCd ipt_listApplntIsurNm
 * @returns
 * @hidden N
*/
scwin.setDigitallistApplntInfo = function (ipt_listApplntIsurCd, ipt_listApplntIsurNm) {
    /* sdd-asis-lifecycle:begin setDigitallistApplntInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_listApplntIsurCd2').setValue(ipt_listApplntIsurCd);
    $c.util.getComponent('ipt_listApplntIsurNm').setValue(ipt_listApplntIsurCd);
    /* sdd-asis-lifecycle:end */
};
